import * as React from 'react';
import * as S from '@primasoftllc/design-system';

export function Example(){
const [value,setValue]=React.useState('important');
return <S.DsRadioGroup label="Какие уведомления получать" value={value} onChange={setValue} options={[{value:'all',label:'Все события'},{value:'important',label:'Только важные',description:'Тревоги и потеря связи'},{value:'none',label:'Не получать'}]}/>;
}

required-form:
import * as React from 'react';
import * as S from '@primasoftllc/design-system';

export function Example(){
const [result,setResult]=React.useState('');
return <form onSubmit={event=>{event.preventDefault();setResult('Выбран формат: '+new FormData(event.currentTarget).get('format'));}} onReset={()=>setResult('')} style={{display:'grid',gap:16}}>
<S.DsRadioGroup label="Формат отчёта" name="format" required options={[{value:'CSV',label:'CSV',description:'Для обработки в других программах'},{value:'XLSX',label:'XLSX',description:'Для работы с электронной таблицей'}]}/>
<div style={{display:'flex',flexWrap:'wrap',gap:8}}><S.DsButton type="submit">Выбрать формат</S.DsButton><S.DsButton type="reset" tone="secondary">Сбросить</S.DsButton></div><p role="status" style={{margin:0}}>{result}</p></form>;
}

